    pins = data.get('pins', {})
    names = sorted(packages)
    best = None

    constraints = {name: [tuple(bounds)] for name, bounds in roots.items()}
    required = set(roots)

    def search(assigned, selected_rows, limits, needed):
        nonlocal best

        for name, version in assigned.items():
            if any(not (low <= version <= high) for low, high in limits.get(name, [])):
                return
            if version in blocked.get(name, []):
                return
            if name in pins and version != pins[name]:
                return

        unresolved = sorted(needed - assigned.keys())
        if not unresolved:
            vector = tuple(assigned.get(name, -1) for name in names)
            if best is None or vector > best[0]:
                best = (vector, dict(assigned))
            return

        name = unresolved[0]
        rows = packages.get(name, [])
        for row in choose(rows):
            version = row['version']
            if version in blocked.get(name, []):
                continue
            if name in pins and version != pins[name]:
                continue
            if any(not (low <= version <= high) for low, high in limits.get(name, [])):
                continue

            next_assigned = dict(assigned)
            next_assigned[name] = version
            next_rows = dict(selected_rows)
            next_rows[name] = row
            next_limits = {key: list(value) for key, value in limits.items()}
            next_needed = set(needed)
