                dep_name = dep['name']
                next_limits.setdefault(dep_name, []).append((dep['min'], dep['max']))
                next_needed.add(dep_name)
            search(next_assigned, next_rows, next_limits, next_needed)

    search({}, {}, constraints, required)
    if best is None:
        return {'error': 'unsatisfiable'}
    return {'versions': best[1]}
